# 1. Standard Template (First True / Leftmost Insertion)
def binary_search_leftmost(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    ans = -1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] >= target:
            if nums[mid] == target:
                ans = mid
            hi = mid - 1 # Try to find earlier match
        else:
            lo = mid + 1
    return ans

# 2. Binary Search on Answer Template (e.g. Koko Bananas)
def min_eating_speed(piles: list[int], h: int) -> int:
    def can_finish(speed: int) -> bool:
        hours = sum((p + speed - 1) // speed for p in piles)
        return hours <= h

    lo, hi = 1, max(piles)
    ans = hi
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if can_finish(mid):
            ans = mid
            hi = mid - 1 # Try smaller speed
        else:
            lo = mid + 1
    return ans

